package com.cowave.search.service

import com.cowave.search.controller.dto.CompileResult
import com.cowave.search.domain.DictionaryWithId
import com.cowave.search.domain.Type
import com.cowave.search.utils.DictionaryBinaryCompile
import org.springframework.stereotype.Service

@Service
class DictionaryService(
    val dictionaryRepository: DictionaryRepository,
    val dictionaryBinaryCompile: DictionaryBinaryCompile,
) {
    fun getByType(
        type: Type,
        page: Int,
        size: Int,
    ): List<DictionaryWithId> = dictionaryRepository.findAllWithPageByType(type, page, size)

    fun searchByWord(
        word: String,
        type: Type,
        isMatch: Boolean,
    ): List<DictionaryWithId> = dictionaryRepository.findByWordAndType(word, type, isMatch)

    fun create(
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.insert(keyword, type, value)
    }

    fun update(
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.update(id, keyword, type, value)
    }

    fun delete(id: String) {
        dictionaryRepository.delete(id)
    }

    fun compile(type: Type): CompileResult {
        val dictionaries = dictionaryRepository.findAllByType(type)
        val pairs = dictionaries.map { it.keyword to it.value }
        val outputFile = dictionaryBinaryCompile.compileToConfiguredPath(pairs, type)

        return CompileResult(
            type = type,
            count = dictionaries.size,
            filePath = outputFile.absolutePath,
            fileSize = outputFile.length(),
        )
    }

    fun compileAll(): List<CompileResult> = Type.entries.map { compile(it) }
}

package com.cowave.search.utils

import com.cowave.search.config.DictionaryConfig
import com.cowave.search.domain.Type
import org.springframework.stereotype.Component
import java.io.File

/**
 * 사전 바이너리 컴파일러
 * ES 인덱스에서 읽은 사전 데이터를 바이너리 파일로 컴파일
 *
 * 기존 Java analysis-product의 사전 바이너리 형식과 100% 호환
 */
@Component
class DictionaryBinaryCompile(
    private val dictionaryConfig: DictionaryConfig,
) {
    /**
     * 설정된 출력 경로 반환
     */
    fun getOutputPath(): String = dictionaryConfig.outputPath

    /**
     * Type에 따른 출력 파일 경로 반환 (설정된 경로 사용)
     */
    fun getOutputFile(type: Type): File = File(dictionaryConfig.outputPath, getOutputFileName(type))

    /**
     * ES에서 조회한 Dictionary 목록을 설정된 경로에 컴파일
     * @param dictionaries ES에서 조회한 사전 데이터 (keyword, value 쌍)
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 생성된 파일
     */
    fun compileToConfiguredPath(
        dictionaries: List<Pair<String?, String?>>,
        type: Type,
        ignoreCase: Boolean = true,
    ): File {
        val outputFile = getOutputFile(type)
        compileFromDictionaries(dictionaries, type, outputFile, ignoreCase)
        return outputFile
    }

    /**
     * 설정된 경로에서 사전 파일 로드
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 로드된 사전 데이터
     */
    fun loadFromConfiguredPath(
        type: Type,
        ignoreCase: Boolean = true,
    ): Any = load(type, getOutputFile(type), ignoreCase)

    /**
     * 기존 Type enum과 매핑하여 사전 컴파일
     * SET 타입: STOP, UNIT, USER, ENGLISH
     * SYNONYM 타입: SYNONYM, UNIT_SYNONYM
     * SPACE 타입: SPACE
     * COMPOUND 타입: COMPOUND
     * MAP 타입: MAP
     * INVERT_MAP 타입: INVERT_MAP
     * CUSTOM 타입: CUSTOM
     * SYSTEM 타입: SYSTEM (TagProb)
     */
    fun compile(
        type: Type,
        data: Any,
        outputFile: File,
    ) {
        outputFile.parentFile?.mkdirs()

        when (type) {
            Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                SetDictionarySerializer.writeTo(data as SetDictionaryData, outputFile)
            }

            Type.SYNONYM, Type.UNIT_SYNONYM -> {
                SynonymDictionarySerializer.writeTo(data as SynonymDictionaryData, outputFile)
            }

            Type.SPACE -> {
                SpaceDictionarySerializer.writeTo(data as SpaceDictionaryData, outputFile)
            }

            Type.COMPOUND -> {
                CompoundDictionarySerializer.writeTo(data as CompoundDictionaryData, outputFile)
            }

            Type.MAP -> {
                MapDictionarySerializer.writeTo(data as MapDictionaryData, outputFile)
            }

            Type.INVERT_MAP -> {
                InvertMapDictionarySerializer.writeTo(data as InvertMapDictionaryData, outputFile)
            }

            Type.CUSTOM -> {
                CustomDictionarySerializer.writeTo(data as CustomDictionaryData, outputFile)
            }

            Type.SYSTEM -> {
                TagProbDictionarySerializer.writeTo(data as TagProbDictionaryData, outputFile)
            }
        }
    }

    /**
     * 바이너리 사전 파일을 읽어서 데이터 객체로 반환
     */
    fun load(
        type: Type,
        inputFile: File,
        ignoreCase: Boolean = true,
    ): Any =
        when (type) {
            Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                SetDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.SYNONYM, Type.UNIT_SYNONYM -> {
                SynonymDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.SPACE -> {
                SpaceDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.COMPOUND -> {
                CompoundDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.MAP -> {
                MapDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.INVERT_MAP -> {
                InvertMapDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.CUSTOM -> {
                CustomDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.SYSTEM -> {
                TagProbDictionarySerializer.readFrom(inputFile, ignoreCase)
            }
        }

    /**
     * ES에서 조회한 Dictionary 목록을 타입별로 컴파일
     * @param dictionaries ES에서 조회한 사전 데이터 (keyword, value 쌍)
     * @param type 사전 타입
     * @param outputFile 출력 파일
     * @param ignoreCase 대소문자 무시 여부
     */
    fun compileFromDictionaries(
        dictionaries: List<Pair<String?, String?>>,
        type: Type,
        outputFile: File,
        ignoreCase: Boolean = true,
    ) {
        val data =
            when (type) {
                Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                    // SET 타입: keyword만 사용
                    val words =
                        dictionaries
                            .mapNotNull { it.first?.trim() }
                            .filter { it.isNotEmpty() }
                            .toSet()
                    SetDictionaryData(words, ignoreCase)
                }

                Type.SYNONYM, Type.UNIT_SYNONYM -> {
                    // SYNONYM 타입: keyword -> value 매핑
                    createSynonymFromPairs(dictionaries, ignoreCase)
                }

                Type.SPACE -> {
                    // SPACE 타입: keyword -> value (공백 분리)
                    createSpaceFromPairs(dictionaries, ignoreCase)
                }

                Type.COMPOUND -> {
                    // COMPOUND 타입: keyword -> value (복합어 분해)
                    createCompoundFromPairs(dictionaries, ignoreCase)
                }

                Type.MAP -> {
                    // MAP 타입: keyword -> value 매핑
                    createMapFromPairs(dictionaries, ignoreCase)
                }

                Type.INVERT_MAP -> {
                    // INVERT_MAP 타입: value -> keyword 역방향 매핑
                    createInvertMapFromPairs(dictionaries, ignoreCase)
                }

                Type.CUSTOM -> {
                    // CUSTOM 타입: 복합 값 타입 지원
                    createCustomFromPairs(dictionaries, ignoreCase)
                }

                Type.SYSTEM -> {
                    // SYSTEM 타입: 품사 태그 확률 사전
                    createSystemFromPairs(dictionaries, ignoreCase)
                }
            }
        compile(type, data, outputFile)
    }

    /**
     * SET 타입 사전 생성
     */
    fun createSetDictionary(
        words: Collection<String>,
        ignoreCase: Boolean = true,
    ): SetDictionaryData = SetDictionaryData(words.toSet(), ignoreCase)

    /**
     * SYNONYM 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createSynonymFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): SynonymDictionaryData {
        val synonymMap = mutableMapOf<String, MutableList<String>>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (value.isNullOrBlank()) continue

            val synonyms = value.split(",").map { it.trim() }.filter { it.isNotEmpty() }

            if (!keyword.isNullOrBlank()) {
                // 단방향: keyword -> synonyms
                val key = keyword.trim()
                synonymMap.getOrPut(key) { mutableListOf() }.addAll(synonyms)
                wordSet.add(key)
                wordSet.addAll(synonyms)
            } else {
                // 양방향: 모든 단어가 서로 동의어
                for (word in synonyms) {
                    val others = synonyms.filter { it != word }
                    synonymMap.getOrPut(word) { mutableListOf() }.addAll(others)
                }
                wordSet.addAll(synonyms)
            }
        }

        return SynonymDictionaryData(synonymMap, wordSet, ignoreCase)
    }

    /**
     * SPACE 타입 사전 생성 (keyword, value 쌍으로부터)
     *
     * Java 원본(SpaceDictionary.java:60-73)과 100% 동일한 로직:
     * 1. values[0]에서 공백을 제거하여 key 생성
     * 2. values[0]을 공백으로 split하여 value 배열 생성 (빈 문자열 포함!)
     * 3. wordSet에는 key와 비-ASCII 단어만 추가
     *
     * IMPORTANT: Java는 split("\\s")를 사용하여 연속 공백 시 빈 문자열이 생성됨
     * 예: "클린  스트라이프" → ["클린", "", "스트라이프"]
     * 빈 문자열은 RuleOne.java:45에서 setDisableEntry() 트리거하여 분석 동작에 영향
     * 바이너리 호환성을 위해 빈 문자열을 그대로 유지해야 함
     */
    private fun createSpaceFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): SpaceDictionaryData {
        val spaceMap = mutableMapOf<String, List<String>>()
        val wordSet = mutableSetOf<String>()
        // Java: Pattern.compile("^[\\x00-\\x7F]*$") - ASCII 패턴
        val asciiPattern = Regex("^[\\x00-\\x7F]*$")

        for ((keyword, value) in pairs) {
            // Java: values[0]만 사용 - ES 데이터에서는 keyword 또는 value 중 하나 사용
            val sourceText = keyword?.takeIf { it.isNotBlank() } ?: value
            if (sourceText.isNullOrBlank()) continue

            // Java: String keyword = String.valueOf(values[0]).replaceAll("\\s", "")
            val key = sourceText.replace(Regex("\\s"), "")
            if (key.isEmpty()) continue

            // Java: String[] list = String.valueOf(values[0]).split("\\s")
            // CRITICAL: "\\s" (단일 공백)를 사용해야 함 - "\\s+"가 아님!
            // 빈 문자열 필터링 하지 않음 - Java와 동일한 동작을 위해
            val splitWords =
                sourceText
                    .split(Regex("\\s"))
                    .map { it.trim() }
            // 빈 문자열 유지: .filter { it.isNotEmpty() } 제거

            spaceMap[key] = splitWords
            wordSet.add(key) // 공백 제거된 키 추가

            // Java: ASCII 패턴 매치 안되는 것만 추가 (비-ASCII 단어만)
            // 빈 문자열은 ASCII로 매치되므로 wordSet에 추가되지 않음
            for (word in splitWords) {
                if (word.isNotEmpty() && !asciiPattern.matches(word)) {
                    wordSet.add(word)
                }
            }
        }

        return SpaceDictionaryData(spaceMap, wordSet, ignoreCase)
    }

    /**
     * COMPOUND 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createCompoundFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): CompoundDictionaryData {
        val compoundMap = mutableMapOf<String, List<String>>()
        val mainWordSet = mutableSetOf<String>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val key = keyword.trim()
            val parts =
                value
                    .split(",")
                    .map { it.trim() }
                    .filter { it.isNotEmpty() }

            compoundMap[key] = parts
            mainWordSet.add(key)
            wordSet.addAll(parts)
        }

        return CompoundDictionaryData(compoundMap, mainWordSet, wordSet, ignoreCase)
    }

    /**
     * MAP 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createMapFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): MapDictionaryData {
        val map = mutableMapOf<String, MutableList<String>>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val key = keyword.trim().replace(Regex("\\s"), "")
            val values = value.split(",").map { it.trim() }.filter { it.isNotEmpty() }

            map.getOrPut(key) { mutableListOf() }.addAll(values)
        }

        return MapDictionaryData(map.mapValues { it.value.toList() }, ignoreCase)
    }

    /**
     * INVERT_MAP 타입 사전 생성 (keyword, value 쌍으로부터)
     * Java InvertMapDictionary.addEntry()와 동일: value를 key로, keyword를 value로 역방향 매핑
     */
    private fun createInvertMapFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): InvertMapDictionaryData {
        val invertedMap = mutableMapOf<String, MutableList<String>>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val originalKey = keyword.trim().replace(Regex("\\s"), "")
            val values = value.split(",").map { it.trim() }.filter { it.isNotEmpty() }

            // Java: map.put(value, new CharSequence[]{keyword})
            for (v in values) {
                invertedMap.getOrPut(v) { mutableListOf() }.add(originalKey)
            }
        }

        return InvertMapDictionaryData(invertedMap.mapValues { it.value.toList() }, ignoreCase)
    }

    /**
     * CUSTOM 타입 사전 생성 (keyword, value 쌍으로부터)
     * 현재는 단순 String 값만 지원 (Java FIXME 주석 참고)
     */
    private fun createCustomFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): CustomDictionaryData {
        val customMap = mutableMapOf<String, MutableList<CustomValue>>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val key = keyword.trim().replace(Regex("\\s"), "")
            wordSet.add(key)

            // 단순 String 값으로 처리
            val customValue = CustomValue.Single(value.trim())
            customMap.getOrPut(key) { mutableListOf() }.add(customValue)
            wordSet.add(value.trim())
        }

        return CustomDictionaryData(customMap.mapValues { it.value.toList() }, wordSet, ignoreCase)
    }

    /**
     * SYSTEM 타입 사전 생성 (품사 태그 확률 - TagProb)
     * ES 데이터 형식: keyword=단어, value="품사태그,확률" (예: "N,-8.0")
     */
    private fun createSystemFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): TagProbDictionaryData {
        val probMap = mutableMapOf<String, MutableList<TagProb>>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val key = keyword.trim()

            // value 형식: "품사태그,확률" (예: "N,-8.0")
            val parts = value.split(",").map { it.trim() }
            if (parts.size >= 2) {
                val posTag = parts[0]
                val probability = parts[1].toDoubleOrNull() ?: continue

                probMap.getOrPut(key) { mutableListOf() }.add(TagProb(posTag, probability))
            }
        }

        return TagProbDictionaryData(probMap.mapValues { it.value.toList() }, ignoreCase)
    }

    /**
     * Type에 따른 출력 파일명 생성
     */
    fun getOutputFileName(type: Type): String =
        when (type) {
            Type.STOP -> "stop.dict"
            Type.UNIT -> "unit.dict"
            Type.USER -> "user.dict"
            Type.ENGLISH -> "english.dict"
            Type.SYNONYM -> "synonym.dict"
            Type.UNIT_SYNONYM -> "unit_synonym.dict"
            Type.SPACE -> "space.dict"
            Type.COMPOUND -> "compound.dict"
            Type.MAP -> "map.dict"
            Type.INVERT_MAP -> "invert_map.dict"
            Type.CUSTOM -> "custom.dict"
            Type.SYSTEM -> "system.dict"
        }
}

package com.cowave.search.controller

import com.cowave.search.controller.dto.CompileResult
import com.cowave.search.controller.dto.CreateDictionaryRequest
import com.cowave.search.controller.dto.UpdateDictionaryRequest
import com.cowave.search.domain.DictionaryWithId
import com.cowave.search.domain.Type
import com.cowave.search.service.DictionaryService
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/api/v1/dictionary")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    @GetMapping("/{type}")
    fun getByType(
        @PathVariable type: Type,
        @RequestParam(defaultValue = "0") page: Int,
        @RequestParam(defaultValue = "20") size: Int,
    ): List<DictionaryWithId> = dictionaryService.getByType(type, page, size)

    @GetMapping("/{type}/search")
    fun search(
        @PathVariable type: Type,
        @RequestParam word: String,
        @RequestParam(defaultValue = "true") isMatch: Boolean,
    ): List<DictionaryWithId> = dictionaryService.searchByWord(word, type, isMatch)

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @PathVariable id: String,
    ) {
        dictionaryService.delete(id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(type)

    @PostMapping("/compile")
    fun compileAll(): List<CompileResult> = dictionaryService.compileAll()
}
